    Q_PROPERTY(bool replyInProgress READ replyInProgress NOTIFY replyInProgressChanged FINAL)

public:
    enum Roles {
        // Basic roles
        MessageRole,
        SenderRole,
        FinishedRole,
        MessageIndexRole,

        // Debug information roles
        TokensPerSecondRole,
        TokenCountRole,
        DurationRole,
    };

    enum Sender {
        LLM,
        User,
    };
    Q_ENUM(Sender)

    explicit ChatModel(QObject *parent = nullptr);
